### tests/test_api.py
```python
from datetime import date
from invoicing.api import create_invoice_handler, get_invoice_handler
from invoicing.invoice import Invoice, LineItem
from invoicing.service import InvoiceService
from invoicing.store import InvoiceStore

def test_create():
    s = InvoiceService(InvoiceStore())
    status, body = create_invoice_handler(s, "asha", {"id": "A2", "items": [{"sku": "pen", "qty": 1, "unit_paise": 10000}]})
    assert status == 201 and body["created"] == date.today().isoformat()

def test_create_invalid_item():
    s = InvoiceService(InvoiceStore())
    status, body = create_invoice_handler(s, "asha", {"id": "A2", "items": [{"sku": "pen", "qty": 0, "unit_paise": 10000}]})
    assert status == 400 and body["error"] == "BAD_QTY"

def test_get():
    s = InvoiceService(InvoiceStore())
    s.create(Invoice("A1", "asha", [LineItem("pen", 1, 10000)], date(2026, 9, 1)))
    status, body = get_invoice_handler(s, "A1", "asha")
    assert status == 200 and body["created"] == "2026-09-01" and body["total"] == 11800
